Node* reverseKGroup(Node* head, int k) {
    // check k nodes exist
    Node* check = head;
    for (int i = 0; i < k; i++) {
        if (!check) return head;          // partial tail: untouched
        check = check->next;
    }
    // reverse exactly this group (L1 trio)
    Node* prev = nullptr, * cur = head;
    for (int i = 0; i < k; i++) {
        Node* ahead = cur->next;
        cur->next = prev;
        prev = cur; cur = ahead;
    }
    // prev = new group head ; old head = new tail
    head->next = reverseKGroup(cur, k);   // MANTRA: rest handled recursively
    return prev;
}

