ListNode* reverseKGroup(ListNode* head, int k) {
    // EXISTENCE CHECK FIRST: a trailing block shorter than k stays untouched
    ListNode* probe = head;
    for (int i = 0; i < k; ++i) {
        if (!probe) return head;
        probe = probe->next;
    }
    // reverse exactly k nodes; cur ends at the (k+1)-th
    ListNode *prev = nullptr, *cur = head;
    for (int i = 0; i < k; ++i) {
        ListNode* ahead = cur->next;
        cur->next = prev;
        prev = cur;
        cur = ahead;
    }
    head->next = reverseKGroup(cur, k);   // old head is now the block's tail
    return prev;                          // prev is the block's new head
}

// Recognition route: this IS reverseKGroup with k fixed at 2.
ListNode* swapPairsViaKGroup(ListNode* head) { return reverseKGroup(head, 2); }

// Standalone iterative route, O(1) space.
ListNode* swapPairs(ListNode* head) {
    ListNode dummy(0); dummy.next = head;
    ListNode* prev = &dummy;
    while (prev->next && prev->next->next) {
        ListNode* a = prev->next;
        ListNode* b = a->next;
        a->next = b->next;      // a jumps over b
        b->next = a;            // b takes a's place
        prev->next = b;         // predecessor now points at b
        prev = a;               // a is the tail of this pair
    }
    return dummy.next;
}

ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;
    int n = 1;
    ListNode* tail = head;
    while (tail->next) { tail = tail->next; ++n; }   // count AND find the tail
    k %= n;                                          // k > n is the classic trap
    if (k == 0) return head;
    tail->next = head;                               // close the ring
    ListNode* newTail = head;
    for (int i = 0; i < n - k - 1; ++i) newTail = newTail->next;
    ListNode* newHead = newTail->next;
    newTail->next = nullptr;                         // cut the ring open
    return newHead;
}

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    stack<int> s1, s2;
    for (ListNode* t = l1; t; t = t->next) s1.push(t->val);
    for (ListNode* t = l2; t; t = t->next) s2.push(t->val);

    ListNode* head = nullptr;      // build by PREPENDING, so digits land MSB-first
    int carry = 0;
    while (!s1.empty() || !s2.empty() || carry) {
        int sum = carry;
        if (!s1.empty()) { sum += s1.top(); s1.pop(); }
        if (!s2.empty()) { sum += s2.top(); s2.pop(); }
        carry = sum / 10;
        ListNode* node = new ListNode(sum % 10);
        node->next = head;         // prepend
        head = node;
    }
    return head;
}

