def add_two_numbers_ii(l1, l2):
    s1, s2 = [], []
    t = l1
    while t:
        s1.append(t.val); t = t.next
    t = l2
    while t:
        s2.append(t.val); t = t.next

    head = None          # build by PREPENDING, so digits land MSB-first
    carry = 0
    while s1 or s2 or carry:
        total = carry
        if s1:
            total += s1.pop()
        if s2:
            total += s2.pop()
        carry, digit = divmod(total, 10)
        head = ListNode(digit, head)   # prepend
    return head

