ListNode* mergeKLists(vector<ListNode*>& lists) {
    auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };  // min-heap
    priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);
    for (ListNode* l : lists) if (l) pq.push(l);

    ListNode dummy(0), *tail = &dummy;
    while (!pq.empty()) {
        ListNode* node = pq.top(); pq.pop();
        tail->next = node; tail = node;
        if (node->next) pq.push(node->next);   // refill from the same list
    }
    tail->next = nullptr;
    return dummy.next;
}

// Each node has next (rightward) and bottom (downward); bottom lists are sorted.
struct FlatNode { int val; FlatNode *next, *bottom; };

FlatNode* mergeBottom(FlatNode* a, FlatNode* b) {
    if (!a) return b;
    if (!b) return a;
    FlatNode* res;
    if (a->val <= b->val) { res = a; res->bottom = mergeBottom(a->bottom, b); }
    else                  { res = b; res->bottom = mergeBottom(a, b->bottom); }
    res->next = nullptr;              // the flattened list has no next pointers
    return res;
}

FlatNode* flatten(FlatNode* root) {
    if (!root || !root->next) return root;
    root->next = flatten(root->next);          // flatten everything to the right
    return mergeBottom(root, root->next);      // then fold this one in
}

