class FlatNode:
    def __init__(self, val=0, nxt=None, bottom=None):
        self.val = val
        self.next = nxt
        self.bottom = bottom


def merge_bottom(a, b):
    dummy = FlatNode()
    tail = dummy
    while a and b:
        if a.val <= b.val:
            tail.bottom, a = a, a.bottom
        else:
            tail.bottom, b = b, b.bottom
        tail = tail.bottom
        tail.next = None          # the flattened list has no next pointers
    tail.bottom = a if a else b
    t = tail.bottom
    while t:
        t.next = None
        t = t.bottom
    return dummy.bottom


def flatten(root):
    if root is None or root.next is None:
        return root
    root.next = flatten(root.next)        # flatten everything to the right
    return merge_bottom(root, root.next)  # then fold this one in

