void reorderList(ListNode* head) {
    if (!head || !head->next) return;
    // 1. FIRST middle, so the second half is never longer than the first
    ListNode *slow = head, *fast = head;
    while (fast->next && fast->next->next) { slow = slow->next; fast = fast->next->next; }

    // 2. reverse the second half and detach it
    ListNode *prev = nullptr, *cur = slow->next;
    slow->next = nullptr;
    while (cur) { ListNode* ahead = cur->next; cur->next = prev; prev = cur; cur = ahead; }

    // 3. weave: alternate one node from each half
    ListNode *a = head, *b = prev;
    while (b) {
        ListNode *na = a->next, *nb = b->next;
        a->next = b;
        b->next = na;
        a = na; b = nb;
    }
}

struct RNode { int val; RNode *next, *random; };

RNode* copyRandomList(RNode* head) {
    if (!head) return nullptr;
    // PASS 1: A -> A' -> B -> B' -> ...
    for (RNode* t = head; t; t = t->next->next) {
        RNode* clone = new RNode{t->val, t->next, nullptr};
        t->next = clone;
    }
    // PASS 2: a clone's random is the ORIGINAL random's clone -- which sits right after it
    for (RNode* t = head; t; t = t->next->next)
        t->next->random = t->random ? t->random->next : nullptr;
    // PASS 3: unweave, restoring the original list
    RNode* newHead = head->next;
    for (RNode* t = head; t; ) {
        RNode* clone = t->next;
        t->next = clone->next;
        clone->next = t->next ? t->next->next : nullptr;
        t = t->next;
    }
    return newHead;
}
